11	// Author: Tan, Zhiyuan
12	// Description: L1 DCache main module
13	
14	`timescale 1ns/1ns
15	
16	`include "define.v"
17	//`include "l1dcache_define.v"
18	
19	module l1_dcache (
20	  input                                                     clk                    ,
21	  input                                                     rst_n                  ,
22	  //coreReq
23	  input                                                     core_req_valid_i       ,
24	  output                                                    core_req_ready_o       ,
25	  input  [`WIDBITS-1:0]                                     core_req_instrid_i     ,
26	  input  [`DCACHE_SETIDXBITS-1:0]                           core_req_setidx_i      ,
27	  input  [`DCACHE_TAGBITS-1:0]                              core_req_tag_i         ,
28	  input  [`DCACHE_NLANES-1:0]                               core_req_activemask_i  ,
29	  input  [`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS-1:0]       core_req_blockoffset_i ,
30	  input  [`DCACHE_NLANES*`BYTESOFWORD-1:0]                  core_req_wordoffset1h_i,
31	  input  [`DCACHE_NLANES*`XLEN-1:0]                         core_req_data_i        ,
32	  input  [2:0]                                              core_req_opcode_i      ,
33	  input  [3:0]                                              core_req_param_i       ,
34	  //coreRsp
35	  output                                                    core_rsp_valid_o       ,
36	  input                                                     core_rsp_ready_i       ,
37	  output                                                    core_rsp_is_write_o    ,
38	  output [`WIDBITS-1:0]                                     core_rsp_instrid_o     ,
39	  output [`DCACHE_NLANES*`XLEN-1:0]                         core_rsp_data_o        ,
40	  output [`DCACHE_NLANES-1:0]                               core_rsp_activemask_o  ,
41	  //memRsp
42	  input                                                     mem_rsp_valid_i        ,
43	  output                                                    mem_rsp_ready_o        ,
44	  input  [2:0]                                              mem_rsp_d_opcode_i     ,
45	  input  [2+$clog2(`DCACHE_MSHRENTRY)+`DCACHE_SETIDXBITS:0] mem_rsp_d_source_i     ,
46	  input  [`XLEN-1:0]                                        mem_rsp_d_addr_i       ,
47	  input  [`DCACHE_BLOCKWORDS*`XLEN-1:0]                     mem_rsp_d_data_i       ,
48	  //memReq
49	  output                                                    mem_req_valid_o        ,
50	  input                                                     mem_req_ready_i        ,
51	  output [2:0]                                              mem_req_a_opcode_o     ,
52	  output [2:0]                                              mem_req_a_param_o      ,
53	  output [2+$clog2(`DCACHE_MSHRENTRY)+`DCACHE_SETIDXBITS:0] mem_req_a_source_o     ,
54	  output [`XLEN-1:0]                                        mem_req_a_addr_o       ,
55	  output [`DCACHE_BLOCKWORDS*`XLEN-1:0]                     mem_req_a_data_o       ,
56	  output [`DCACHE_BLOCKWORDS*`BYTESOFWORD-1:0]              mem_req_a_mask_o       
57	);
58	
59	  localparam CORE_RSP_Q_ENTRIES = `DCACHE_NLANES                       ;
60	  localparam SRAM_NSETS         = `DCACHE_NSETS * `DCACHE_NWAYS        ;
61	  localparam SRAM_SETIDXBITS    = $clog2(SRAM_NSETS)                   ;
62	  localparam WM_ENTRY_EQUAL     = `DCACHE_MSHRENTRY==`DCACHE_WSHR_ENTRY;
63	
64	  //Queue: coreReq_Q
65	  wire core_req_enq_valid;
66	  wire core_req_enq_ready;
67	  wire core_req_deq_valid;
68	  wire core_req_deq_ready;
69	  wire [`WIDBITS+`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:0] core_req_enq_bits;
70	  wire [`WIDBITS+`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:0] core_req_deq_bits;
71	
72	  assign core_req_enq_bits = {core_req_instrid_i     ,
73	                              core_req_setidx_i      ,
74	                              core_req_tag_i         ,
75	                              core_req_activemask_i  ,
76	                              core_req_blockoffset_i ,
77	                              core_req_wordoffset1h_i,
78	                              core_req_data_i        ,
79	                              core_req_opcode_i      ,
80	                              core_req_param_i       };
81	
82	  stream_fifo_pipe_true #(
83	    .DATA_WIDTH (`WIDBITS+`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7),
84	    .FIFO_DEPTH (1)
85	  )
86	  core_req_q (
87	    .clk       (clk               ),
88	    .rst_n     (rst_n             ),
89	    .w_ready_o (core_req_enq_ready),
90	    .w_valid_i (core_req_enq_valid),
91	    .w_data_i  (core_req_enq_bits ),
92	    .r_valid_o (core_req_deq_valid),
93	    .r_ready_i (core_req_deq_ready),
94	    .r_data_o  (core_req_deq_bits )
95	  );
96	
97	  //Queue: coreReq_st1
98	  wire [`WIDBITS-1:0]                               core_req_instrid_st1     ;
99	  wire [`DCACHE_SETIDXBITS-1:0]                     core_req_setidx_st1      ;
100	  wire [`DCACHE_TAGBITS-1:0]                        core_req_tag_st1         ;
101	  wire [`DCACHE_NLANES-1:0]                         core_req_activemask_st1  ;
102	  wire [`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS-1:0] core_req_blockoffset_st1 ;
103	  wire [`DCACHE_NLANES*`BYTESOFWORD-1:0]            core_req_wordoffset1h_st1;
104	  wire [`DCACHE_NLANES*`XLEN-1:0]                   core_req_data_st1        ;
105	  wire [2:0]                                        core_req_opcode_st1      ;
106	  wire [3:0]                                        core_req_param_st1       ;
107	
108	  assign core_req_instrid_st1      = core_req_deq_bits[`WIDBITS+`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7];
109	  assign core_req_setidx_st1       = core_req_deq_bits[`DCACHE_SETIDXBITS+`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7];
110	  assign core_req_tag_st1          = core_req_deq_bits[`DCACHE_TAGBITS+`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7];
111	  assign core_req_activemask_st1   = core_req_deq_bits[`DCACHE_NLANES+`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7];
112	  assign core_req_blockoffset_st1  = core_req_deq_bits[`DCACHE_NLANES*`DCACHE_BLOCKOFFSETBITS+`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+7];
113	  assign core_req_wordoffset1h_st1 = core_req_deq_bits[`DCACHE_NLANES*`BYTESOFWORD+`DCACHE_NLANES*`XLEN+6:`DCACHE_NLANES*`XLEN+7];
114	  assign core_req_data_st1         = core_req_deq_bits[`DCACHE_NLANES*`XLEN+6:7];
115	  assign core_req_opcode_st1       = core_req_deq_bits[6:4];
116	  assign core_req_param_st1        = core_req_deq_bits[3:0];
117	
118	  //tag access
119	  wire                                        tag_probeRead_valid               ;
120	  wire                                        tag_probeRead_ready               ;
121	  wire [`DCACHE_SETIDXBITS-1:0]               tag_probeRead_setIdx              ;
122	  wire [`DCACHE_TAGBITS-1:0]                  tag_tagFromCore_st1               ;
123	  wire                                        tag_probeIsWrite_st1              ;
124	  wire                                        tag_coreReq_q_deq_fire            ;
125	  wire                                        tag_hit_st1                       ;
126	  wire [`DCACHE_NWAYS-1:0]                    tag_waymaskHit_st1                ;
127	  wire                                        tag_allocateWrite_valid           ;
128	  wire [`DCACHE_SETIDXBITS-1:0]               tag_allocateWrite_setIdx          ;
129	  wire [`DCACHE_TAGBITS-1:0]                  tag_allocateWriteData_st1         ;
130	  wire                                        tag_mem_req_fire                  ;
131	  wire                                        tag_allocateWriteTagSRAMWValid_st1;
132	  wire                                        tag_needReplace                   ;
133	  wire [`DCACHE_NWAYS-1:0]                    tag_waymaskReplacement_st1        ;
134	  wire [`XLEN-1:0]                            tag_addrReplacement_st1           ;
135	  wire                                        tag_hasDirty_st0                  ;
136	  wire [`DCACHE_SETIDXBITS-1:0]               tag_dirtySetIdx_st0               ;
137	  wire [$clog2(`DCACHE_NWAYS)-1:0]            tag_dirtyWayMask_st0              ;
138	  wire [`DCACHE_TAGBITS-1:0]                  tag_dirtyTag_st1                  ;
139	  wire                                        tag_flushChoosen_valid            ;
140	  wire [`DCACHE_SETIDXBITS+`DCACHE_NWAYS-1:0] tag_flushChoosen                  ;
141	  wire                                        tag_invalidateAll                 ;
142	  wire                                        tag_tagready_st1                  ;
143	
144	  tag_access_top_v2 #(
145	    .NUM_SET  (`DCACHE_NSETS  ),
146	    .NUM_WAY  (`DCACHE_NWAYS  ),
147	    .TAG_BITS (`DCACHE_TAGBITS)
148	  )
149	  tagaccess (
150	    .clk                              (clk                               ),
151	    .rst_n                            (rst_n                             ),
152	    .probeRead_valid_i                (tag_probeRead_valid               ),
153	    .probeRead_ready_o                (tag_probeRead_ready               ),
154	    .probeRead_setIdx_i               (tag_probeRead_setIdx              ),
155	    .tagFromCore_st1_i                (tag_tagFromCore_st1               ),
156	    .probeIsWrite_st1_i               (tag_probeIsWrite_st1              ),
157	    .coreReq_q_deq_fire_i             (tag_coreReq_q_deq_fire            ),
158	    .hit_st1_o                        (tag_hit_st1                       ),
159	    .waymaskHit_st1_o                 (tag_waymaskHit_st1                ),
160	    .allocateWrite_valid_i            (tag_allocateWrite_valid           ),
161	    .allocateWrite_setIdx_i           (tag_allocateWrite_setIdx          ),
162	    .allocateWriteData_st1_i          (tag_allocateWriteData_st1         ),
163	    .mem_req_fire_i                   (tag_mem_req_fire                  ),
164	    .allocateWriteTagSRAMWValid_st1_i (tag_allocateWriteTagSRAMWValid_st1),
165	    .needReplace_o                    (tag_needReplace                   ),
166	    .waymaskReplacement_st1_o         (tag_waymaskReplacement_st1        ),
167	    .addrReplacement_st1_o            (tag_addrReplacement_st1           ),
168	    .hasDirty_st0_o                   (tag_hasDirty_st0                  ),
169	    .dirtySetIdx_st0_o                (tag_dirtySetIdx_st0               ),
170	    .dirtyWayMask_st0_o               (tag_dirtyWayMask_st0              ),
171	    .dirtyTag_st1_o                   (tag_dirtyTag_st1                  ),
172	    .flushChoosen_valid_i             (tag_flushChoosen_valid            ),
173	    .flushChoosen_i                   (tag_flushChoosen                  ),
174	    .invalidateAll_i                  (tag_invalidateAll                 ),
175	    .tagready_st1_i                   (tag_tagready_st1                  )
176	  );
177	
178	  //mshr
179	  wire                                 mshr_probe_valid           ;
180	  wire [`BABITS-1:0]                   mshr_probe_blockaddr       ;
181	  wire                                 mshr_missreq_valid         ;
182	  wire                                 mshr_missreq_ready         ;
183	  wire [`BABITS-1:0]                   mshr_missreq_blockaddr     ;
184	  wire [`TIWIDTH-1:0]                  mshr_missreq_targetinfo    ;
185	  wire                                 mshr_missrsp_in_valid      ;
186	  wire                                 mshr_missrsp_in_ready      ;
187	  wire [$clog2(`DCACHE_MSHRENTRY)-1:0] mshr_missrsp_in_instrid    ;
188	  wire                                 mshr_missrsp_out_valid     ;
189	  wire [`BABITS-1:0]                   mshr_missrsp_out_blockaddr ;
190	  wire [`TIWIDTH-1:0]                  mshr_missrsp_out_targetinfo;
191	  wire                                 mshr_empty                 ;
192	  wire                                 mshr_probe_status          ;
193	  wire [2:0]                           mshr_mshr_status_st0       ;
194	  wire [2:0]                           mshr_probe_out_mshr_status ;
195	  wire [$clog2(`DCACHE_MSHRENTRY)-1:0] mshr_probe_out_a_source    ;
196	  wire                                 mshr_stage1_ready          ;
197	  wire                                 mshr_stage2_ready          ;
198	
199	  l1_mshr mshraccess (
200	    .clk                      (clk                        ),
201	    .rst_n                    (rst_n                      ),
202	    .probe_valid_i            (mshr_probe_valid           ),
203	    .probe_blockaddr_i        (mshr_probe_blockaddr       ),
204	    .missreq_valid_i          (mshr_missreq_valid         ),
205	    .missreq_ready_o          (mshr_missreq_ready         ),
206	    .missreq_blockaddr_i      (mshr_missreq_blockaddr     ),
207	    .missreq_targetinfo_i     (mshr_missreq_targetinfo    ),
208	    .missrsp_in_valid_i       (mshr_missrsp_in_valid      ),
209	    .missrsp_in_ready_o       (mshr_missrsp_in_ready      ),
210	    .missrsp_in_instrid_i     (mshr_missrsp_in_instrid    ),
211	    .missrsp_out_valid_o      (mshr_missrsp_out_valid     ),
212	    .missrsp_out_blockaddr_o  (mshr_missrsp_out_blockaddr ),
213	    .missrsp_out_targetinfo_o (mshr_missrsp_out_targetinfo),
214	    .empty_o                  (mshr_empty                 ),
215	    .probe_status_o           (mshr_probe_status          ),
216	    .mshr_status_st0_o        (mshr_mshr_status_st0       ),
217	    .probe_out_mshr_status_o  (mshr_probe_out_mshr_status ),
218	    .probe_out_a_source_o     (mshr_probe_out_a_source    ),
219	    .stage1_ready_i           (mshr_stage1_ready          ),
220	    .stage2_ready_i           (mshr_stage2_ready          )
221	  );
222	
223	  //indicate read/write miss/hit
224	  wire cache_hit_st1 ;
225	  wire cache_miss_st1;
226	  wire read_hit_st1  ;
227	  wire read_miss_st1 ;
228	  wire write_hit_st1 ;
229	  wire write_miss_st1;
230	
231	  //for handshake
232	  reg  inflight_read_write_miss    ;
233	
234	  wire readmiss_same_addr          ;
235	  wire proberead_allocatewrite_conf;
236	  wire inflight_read_write_miss_w  ;
237	
238	  //these handshake signals indicate: when the memRsp comes, whether the coreReq is blocked
239	  wire core_req_st0_ready          ;
240	  //wire core_req_st0_valid          ;
241	  reg  core_req_st1_ready          ;
242	  wire core_req_st1_valid          ;
243	  
244	
245	  //coreReq handshake signals
246	  assign core_req_enq_valid = core_req_valid_i && core_req_ready_o && !proberead_allocatewrite_conf && tag_probeRead_ready && (mshr_mshr_status_st0!=3'b011) && (mshr_mshr_status_st0!=3'b001);
247	  assign core_req_deq_ready = core_req_st1_ready && !((core_req_opcode_st1==4'b0011)&&read_hit_st1&&core_req_st1_valid);
248	
249	  //core_req_st0 ready
250	  assign core_req_st0_ready = core_req_enq_ready && !proberead_allocatewrite_conf && !inflight_read_write_miss_w && !readmiss_same_addr && tag_probeRead_ready && (mshr_mshr_status_st0!=3'b011) && (mshr_mshr_status_st0!=3'b001);
251	
252	  //secondary full return
253	  reg secondary_full_return;
254	  
255	  always@(posedge clk or negedge rst_n) begin
256	    if(!rst_n) begin
257	      secondary_full_return <= 'd0;
258	    end
259	    else begin
260	      secondary_full_return <= (mshr_probe_out_mshr_status==3'b100);
261	    end
262	  end
263	
264	  //control signals: st0
265	  wire is_read_noen      ;
266	  wire is_write_noen     ;
267	  wire is_lr_noen        ;
268	  wire is_sc_noen        ;
269	  wire is_amo_noen       ;
270	  wire is_flush_noen     ;
271	  wire is_invalidate_noen;
272	  wire is_wait_mshr_noen ;
273	
274	  wire is_read_st0      ;
275	  wire is_write_st0     ;
276	  wire is_lr_st0        ;
277	  wire is_sc_st0        ;
278	  wire is_amo_st0       ;
279	  wire is_flush_st0     ;
280	  wire is_invalidate_st0;
281	  wire is_wait_mshr_st0 ;
282	
283	  dcache_control control_gen (
284	    .opcode        (core_req_opcode_i ),
285	    .param         (core_req_param_i  ),
286	    .is_read       (is_read_noen      ),
287	    .is_write      (is_write_noen     ),
288	    .is_lr         (is_lr_noen        ),
289	    .is_sc         (is_sc_noen        ),
290	    .is_amo        (is_amo_noen       ),
291	    .is_flush      (is_flush_noen     ),
292	    .is_invalidate (is_invalidate_noen),
293	    .is_wait_mshr  (is_wait_mshr_noen )
294	  );
295	
296	  assign is_read_st0       = (core_req_valid_i&&core_req_ready_o) ? is_read_noen       : 'd0;
297	  assign is_write_st0      = (core_req_valid_i&&core_req_ready_o) ? is_write_noen      : 'd0;
298	  assign is_lr_st0         = (core_req_valid_i&&core_req_ready_o) ? is_lr_noen         : 'd0;
299	  assign is_sc_st0         = (core_req_valid_i&&core_req_ready_o) ? is_sc_noen         : 'd0;
300	  assign is_amo_st0        = (core_req_valid_i&&core_req_ready_o) ? is_amo_noen        : 'd0;
301	  assign is_flush_st0      = (core_req_valid_i&&core_req_ready_o) ? is_flush_noen      : 'd0;
302	  assign is_invalidate_st0 = (core_req_valid_i&&core_req_ready_o) ? is_invalidate_noen : 'd0;
303	  assign is_wait_mshr_st0  = (core_req_valid_i&&core_req_ready_o) ? is_wait_mshr_noen  : 'd0;
304	
305	  //Queue: coreReqControl_st1_Q
306	  wire is_read_st1      ;
307	  wire is_write_st1     ;
308	  wire is_lr_st1        ;
309	  wire is_sc_st1        ;
310	  wire is_amo_st1       ;
311	  wire is_flush_st1     ;
312	  wire is_invalidate_st1;
313	  wire is_wait_mshr_st1 ;
314	
315	  wire       core_req_control_st1_enq_valid;
316	  wire       core_req_control_st1_enq_ready;
317	  wire [7:0] core_req_control_st1_enq_bits ;
318	  wire       core_req_control_st1_deq_valid;
319	  wire       core_req_control_st1_deq_ready;
320	  wire [7:0] core_req_control_st1_deq_bits ;
321	
322	  assign core_req_control_st1_enq_bits = {is_read_st0      ,
323	                                          is_write_st0     ,
324	                                          is_lr_st0        ,
325	                                          is_sc_st0        ,
326	                                          is_amo_st0       ,
327	                                          is_flush_st0     ,
328	                                          is_invalidate_st0,
329	                                          is_wait_mshr_st0 };
330	
331	  stream_fifo_pipe_true #(
332	    .DATA_WIDTH (8),
333	    .FIFO_DEPTH (1)
334	  )
335	  core_req_control_st1_q (
336	    .clk       (clk                           ),
337	    .rst_n     (rst_n                         ),
338	    .w_ready_o (core_req_control_st1_enq_ready),
339	    .w_valid_i (core_req_control_st1_enq_valid),
340	    .w_data_i  (core_req_control_st1_enq_bits ),
341	    .r_valid_o (core_req_control_st1_deq_valid),
342	    .r_ready_i (core_req_control_st1_deq_ready),
343	    .r_data_o  (core_req_control_st1_deq_bits )
344	  );
345	
346	  assign is_read_st1       = core_req_control_st1_deq_bits[7];
347	  assign is_write_st1      = core_req_control_st1_deq_bits[6];
348	  assign is_lr_st1         = core_req_control_st1_deq_bits[5];
349	  assign is_sc_st1         = core_req_control_st1_deq_bits[4];
350	  assign is_amo_st1        = core_req_control_st1_deq_bits[3];
351	  assign is_flush_st1      = core_req_control_st1_deq_bits[2];
352	  assign is_invalidate_st1 = core_req_control_st1_deq_bits[1];
353	  assign is_wait_mshr_st1  = core_req_control_st1_deq_bits[0];
354	
355	  //handshake signals: coreReqControl_st1_Q
356	  assign core_req_control_st1_enq_valid = core_req_valid_i && core_req_ready_o;
357	  assign core_req_control_st1_deq_ready = core_req_st1_ready                  ;
358	  assign core_req_control_st1_deq_fire  = core_req_control_st1_deq_valid && core_req_control_st1_deq_ready;
359	
360	  //RegNext(inject_tag_probe), after inflightReadWriteMiss come back, use it;
361	  reg inject_tag_probe_reg             ;
362	  reg core_req_control_st1_deq_fire_reg;
