1430	        .rst_n           (rst_n                       ),
1431	        .r_req_valid_i   (data_access_r_req_valid[i]  ),
1432	        .r_req_setid_i   (data_access_r_req_setid[i]  ),
1433	        .r_resp_data_o   (data_access_r_resp_data[i]  ),
1434	        .w_req_valid_i   (data_access_w_req_valid[i]  ),
1435	        .w_req_setid_i   (data_access_w_req_setid[i]  ),
1436	        .w_req_waymask_i (data_access_w_req_waymask[i]),
1437	        .w_req_data_i    (data_access_w_req_data[i]   )
1438	      );
1439	
1440	      assign data_access_rrsp[`XLEN*(i+1)-1 -:`XLEN] = data_access_r_resp_data[i];
1441	
1442	    end
1443	  endgenerate
1444	
1445	  //coreRsp_st2 connection:
1446	  reg                            core_rsp_st2_enq_is_write  ;
1447	  reg [`WIDBITS-1:0]             core_rsp_st2_enq_instrid   ;
1448	  reg [`DCACHE_NLANES*`XLEN-1:0] core_rsp_st2_enq_data      ;
1449	  reg [`DCACHE_NLANES-1:0]       core_rsp_st2_enq_activemask;
1450	
1451	  wire                            core_rsp_st2_deq_is_write  ;
1452	  wire [`WIDBITS-1:0]             core_rsp_st2_deq_instrid   ;
1453	  wire [`DCACHE_NLANES*`XLEN-1:0] core_rsp_st2_deq_data      ;
1454	  wire [`DCACHE_NLANES-1:0]       core_rsp_st2_deq_activemask;
1455

