1873	    .DATA_WIDTH (`DCACHE_NLANES),
1874	    .FIFO_DEPTH (32)
1875	  )
1876	  core_req_mask_q (
1877	    .clk       (clk                      ),
1878	    .rst_n     (rst_n                    ),
1879	    .w_ready_o (core_req_mask_q_enq_ready),
1880	    .w_valid_i (core_req_mask_q_enq_valid),
1881	    .w_data_i  (core_req_mask_q_enq_bits ),
1882	    .r_valid_o (core_req_mask_q_deq_valid),
1883	    .r_ready_i (core_req_mask_q_deq_ready),
1884	    .r_data_o  (core_req_mask_q_deq_bits )
1885	  );
1886	
1887	  //coreReqMask_Q connection
1888	  assign core_req_mask_q_enq_valid = mem_req_q_enq_valid                        ;
1889	  assign core_req_mask_q_deq_ready = mem_req_q_deq_ready && mem_req_q_deq_valid && core_rsp_q_enq_ready &&
1890	    !(wshr_conflict && (mem_req_is_write_st3||mem_req_is_read_st3)) && ! (mem_req_is_write_st3 && !push_wshr_valid);
1891	  assign core_req_mask_q_enq_bits  = core_req_activemask_st1                    ;
1892	
1893	  reg [`DCACHE_NLANES-1:0] core_req_mask_q_deq_bits_reg;
1894	
1895	  always@(posedge clk or negedge rst_n) begin
1896	    if(!rst_n) begin
1897	      core_req_mask_q_deq_bits_reg <= 'd0;
1898	    end
1899	    else if(core_req_mask_q_deq_valid && core_req_mask_q_deq_ready) begin
1900	      core_req_mask_q_deq_bits_reg <= core_req_mask_q_deq_bits;
1901	    end
1902	    else begin
1903	      core_req_mask_q_deq_bits_reg <= core_req_mask_q_deq_bits_reg;
1904	    end
1905	  end
1906	
1907	  //corersp_from_memreq connection
1908	  assign corersp_from_memreq_is_write   = 1'b1                         ;
1909	  assign corersp_from_memreq_instrid    = mem_req_q_deq_corersp_instrid;
1910	  assign corersp_from_memreq_activemask = core_req_mask_q_deq_bits;//(core_req_mask_q_deq_valid && core_req_mask_q_deq_ready) ? core_req_mask_q_deq_bits : core_req_mask_q_deq_bits_reg;
1911	
1912	  //mem_req_valid
1913	  reg mem_req_valid;
1914	
1915	  always@(posedge clk or negedge rst_n) begin
1916	    if(!rst_n) begin
1917	      mem_req_valid <= 'd0;
1918	    end
1919	    else begin
1920	      mem_req_valid <= ((mem_req_q_deq_valid&&mem_req_q_deq_ready) ^ (mem_req_valid_o&&mem_req_ready_i)) ? (mem_req_q_deq_valid&&mem_req_q_deq_ready) : mem_req_valid;
1921	    end
1922	  end
1923	
1924	  //outputs
1925	  assign core_req_ready_o = core_req_enq_ready && !proberead_allocatewrite_conf && !inflight_read_write_miss_w && !inject_tag_probe && !readmiss_same_addr && tag_probeRead_ready && (mshr_mshr_status_st0!=3'b011) && (mshr_mshr_status_st0!=3'b001) && !mem_req_q_alm_full;
1926	  assign mem_rsp_ready_o  = mem_rsp_q_enq_ready;
1927	
1928	  //assign core_rsp_valid_o      = core_rsp_q_deq_valid                                             ;
1929	  assign core_rsp_valid_o      = core_rsp_q_deq_valid && core_rsp_q_deq_ready                     ;
1930	  assign core_rsp_is_write_o   = core_rsp_q_deq_bits[`WIDBITS+`DCACHE_NLANES*`XLEN+`DCACHE_NLANES];
1931	  assign core_rsp_instrid_o    = core_rsp_q_deq_bits[`WIDBITS+`DCACHE_NLANES*`XLEN+`DCACHE_NLANES-1 -:`WIDBITS];
1932	  assign core_rsp_data_o       = core_rsp_q_deq_bits[`DCACHE_NLANES*`XLEN+`DCACHE_NLANES-1:`DCACHE_NLANES];
1933	  assign core_rsp_activemask_o = core_rsp_q_deq_bits[`DCACHE_NLANES-1:0];
1934	
1935	  assign mem_req_valid_o       = mem_req_valid       ;
1936	  assign mem_req_a_opcode_o    = mem_req_st3_a_opcode;
1937	  assign mem_req_a_param_o     = mem_req_st3_a_param ;
1938	  assign mem_req_a_source_o    = mem_req_st3_a_source;
1939	  assign mem_req_a_addr_o      = mem_req_st3_a_addr  ;
1940	  assign mem_req_a_data_o      = mem_req_st3_a_data  ;
