458	    .NUM_SET   (NUM_SET           ) ,
459	    .NUM_WAY   (NUM_WAY           ) , //way should >= 1
460	    .SET_DEPTH ($clog2(NUM_SET)   ) ,
461	    .WAY_DEPTH ($clog2(NUM_WAY)   )  
462	    )
463	  U_tag_body_access
464	    (
465	    .clk            (clk                                ),
466	    .rst_n          (rst_n                              ),
467	    .r_req_valid_i  (tagAccessRArb_out_valid            ),
468	    .r_req_setid_i  (tagAccessRArb_out_setIdx           ), 
469	    .r_resp_data_o  (tagBodyAccess_resp_data            ), //[GEN_WIDTH-1:0] [0:NUM_WAY-1]
470	    .w_req_valid_i  (/*allocateWrite_fire_q*/ allocateWriteTagSRAMWValid_st1_i   ),
471	    .w_req_setid_i  (allocateWrite_setIdx_st1           ),
472	    .w_req_waymask_i(replacement_waymask_st1_oh                  ), 
473	    .w_req_data_i   ({NUM_WAY{allocateWriteData_st1_i}} )  
474	    );
475	
476	  fixed_pri_arb #(
477	    .ARB_WIDTH(3)
478	  )
479	  U_fixed_pri_tagAccessRArb
480	  (
481	    .req  (tagAccessRArb_in_valid     ),
482	    .grant(tagAccessRArb_valid_oh     )
483	  );
484	
485	  one2bin #(
486	    .ONE_WIDTH(3),
487	    .BIN_WIDTH(2)
488	  )
489	  U_one2bin_tagAccessRArb
490	  (
491	    .oh(tagAccessRArb_valid_oh      ),
492	    .bin(tagAccessRArb_valid_bin    )    
493	  );
494	
495	  genvar k;
496	  generate
497	    for(k=0; k<NUM_SET; k=k+1) begin:lru_module_loop
498	      
499	      lru_matrix #(
500	        .NUM_WAY  (NUM_WAY        ),
501	        .WAY_DEPTH($clog2(NUM_WAY))
502	        )
503	      U_lru_matrix
504	        (
505	        .clk               (clk                                                       ),
506	        .rst_n             (rst_n                                                     ),
507	        .update_entry_i    (lru_update_entry[k]                                       ),
508	        .update_index_i    (lru_update_index                                          ),
509	        .lru_index_o       (lru_index_out[$clog2(NUM_WAY)*(k+1)-1-:$clog2(NUM_WAY)]   )
510	        );
511	
512	    end
513	  endgenerate
514	
515	  bin2one #(
516	    .ONE_WIDTH(NUM_WAY),
517	    .BIN_WIDTH($clog2(NUM_WAY))
518	  )
519	  U_bin2one_lru_index_out
520	  (
521	    .bin  (replacement_waymask_st1_bin   ),
522	    .oh   (replacement_waymask_st1_oh    )    
523	  );
524	
525	
526	
527	  tag_checker #(
528	    .NUM_WAY   (NUM_WAY   ),
529	    .TAG_BITS  (TAG_BITS  )    
530	  )
531	  U_tag_checker
532	  (
533	    .tag_of_set_i       (tagchecker_tag_of_set     ) ,
534	    .tag_from_pipe_i    (tagchecker_tag_from_pipe  ) ,
535	    .valid_of_way_i     (tagchecker_valid_of_way   ) ,
536	    .waymask_o          (tagchecker_waymask        ) , //  onehot
537	    .cache_hit_o        (tagchecker_cache_hit      )  
538	  
539	  );
540	
541	
542	  stream_fifo #(
543	    .DATA_WIDTH ( NUM_WAY+1         ),
544	    .FIFO_DEPTH ( 1                 ) //can't be zero
545	    )
546	  U_cacheHit_hold
547	    (
548	    .clk      (clk                     ),
549	    .rst_n    (rst_n                   ),
550	    .w_ready_o(cacheHit_hold_w_ready   ),
551	    .w_valid_i(cacheHit_hold_w_valid   ),
552	    .w_data_i (cacheHit_hold_w_data    ),
553	    .r_valid_o(cacheHit_hold_r_valid   ),
554	    .r_ready_i(cacheHit_hold_r_ready   ),
555	    .r_data_o (cacheHit_hold_r_data    )
556	    );
557	
558	  one2bin #(
559	    .ONE_WIDTH(NUM_WAY        ),
560	    .BIN_WIDTH($clog2(NUM_WAY))
561	  )
562	  U_one2bin_tagchecker_waymask
563	  (
564	    .oh(tagchecker_waymask          ),
565	    .bin(tagchecker_waymask_bin     )    
566	  );
567	  
568	  /*
569	  fixed_pri_arb #(
570	    .ARB_WIDTH(NUM_SET)
571	  )
572	  U_fixed_pri_set_dirty
573	  (
574	    .req  (set_dirty         ),
575	    .grant(set_dirty_oh      )
576	  );
577	
578	  one2bin #(
579	    .ONE_WIDTH(NUM_SET        ),
580	    .BIN_WIDTH($clog2(NUM_SET))
581	  )
582	  U_one2bin_set_dirty
583	  (
584	    .oh(set_dirty_oh      ),
585	    .bin(set_dirty_bin    )    
586	  );
587	  */
588	
589	  lzc #(
590	    .WIDTH     (NUM_SET        ),
591	    .MODE      (1'b0           ),
592	    .CNT_WIDTH ($clog2(NUM_SET))
593	  )
594	  x_bin (
595	    .in_i    (set_dirty     ),
596	    .cnt_o   (set_dirty_bin ),
597	    .empty_o (set_dirty_zero)
598	  );
599	
600	
601	  fixed_pri_arb #(
602	    .ARB_WIDTH(NUM_WAY)
603	  )
604	  U_fixed_pri_choosenDirty_set_valid
605	  (
606	    .req  (choosenDirty_set_valid         ),
607	    .grant(choosenDirty_set_valid_oh      )
608	  );
609	
610	  
611	  one2bin #(
612	    .ONE_WIDTH(NUM_WAY        ),
613	    .BIN_WIDTH($clog2(NUM_WAY))
614	  )
615	  U_one2bin_chooseDirty_set_valid
616	  (
617	    .oh (choosenDirty_set_valid_oh ),
618	    .bin(choosenDirty_set_valid_bin)    
619	  );
620	  
621	  one2bin #(
622	    .ONE_WIDTH(NUM_WAY        ),
623	    .BIN_WIDTH($clog2(NUM_WAY))
624	  )
625	  flush_choosen_waymask_oh2bin
626	  (
627	    .oh (flushChoosen_waymask    ),
628	    .bin(flushChoosen_waymask_bin)    
629	  );
630	
631	
632	
633	
634	endmodule
